<script setup lang="ts">
import { computed, ref } from "vue";
import { api, errorMessage, jsonRequest } from "@/api/client";
import type { LocationSummary, TripDetail } from "@/api/types";

const props = defineProps<{ trip: TripDetail | null; locations: LocationSummary[] }>();
const emit = defineEmits<{ close: []; saved: [trip: TripDetail] }>();
const name = ref(props.trip?.custom_name || ""); const startedAt = ref(props.trip?.started_at || ""); const endedAt = ref(props.trip?.ended_at || ""); const notes = ref(props.trip?.notes || "");
const selectedIds = ref<number[]>((props.trip?.locations || props.locations.slice(0, 1)).map((item) => item.id));
const primaryId = ref<number | null>(props.trip?.location.id || selectedIds.value[0] || null); const addId = ref(""); const status = ref(props.locations.length ? "" : "请先建立至少一个观鸟地点。");
const selected = computed(() => selectedIds.value.map((id) => props.locations.find((item) => item.id === id)).filter((item): item is LocationSummary => Boolean(item)));
const unselected = computed(() => props.locations.filter((item) => !selectedIds.value.includes(item.id)));
function add(): void { const id = Number(addId.value); if (id && !selectedIds.value.includes(id)) selectedIds.value.push(id); addId.value = ""; }
function remove(id: number): void { if (selectedIds.value.length === 1) return; selectedIds.value = selectedIds.value.filter((value) => value !== id); if (primaryId.value === id) primaryId.value = selectedIds.value[0]; }
function move(index: number, direction: -1 | 1): void { const target = index + direction; if (target < 0 || target >= selectedIds.value.length) return; [selectedIds.value[index], selectedIds.value[target]] = [selectedIds.value[target], selectedIds.value[index]]; }
async function submit(): Promise<void> { if (!primaryId.value || !selectedIds.value.length) { status.value = "远征必须至少包含一个地点。"; return; } status.value = "正在保存…"; try { const payload = { name: name.value || null, location_id: primaryId.value, location_ids: selectedIds.value, primary_location_id: primaryId.value, started_at: startedAt.value, ended_at: endedAt.value, notes: notes.value || null }; const saved = await api<TripDetail>(props.trip ? `/api/trips/${props.trip.id}` : "/api/trips", jsonRequest(props.trip ? "PUT" : "POST", payload)); emit("saved", saved); } catch (caught) { status.value = errorMessage(caught); } }
</script>

<template>
  <form @submit.prevent="submit"><header class="dialog-header"><div><p class="eyebrow">TRIP ARCHIVE</p><h2>{{ trip ? "修改观鸟行程" : "创建观鸟行程" }}</h2></div><button type="button" class="icon-button" @click="$emit('close')">×</button></header><div class="form-scroll"><fieldset><legend><span>01</span> 远征名称、时间与地点</legend><div class="form-grid"><label class="full-field">远征名称<input v-model="name" type="text" maxlength="180" placeholder="例如：兴隆山春季观鸟；留空时使用主要地点名称" /></label><div class="full-field"><span class="field-label">远征地点与行程顺序</span><p class="field-hint">勾选多个地点，指定一个主要地点，并用箭头调整到访顺序。</p><div class="trip-location-selection"><article v-for="(location, index) in selected" :key="location.id" class="trip-location-row"><span class="trip-location-order">{{ String(index + 1).padStart(2, "0") }}</span><label><input v-model="primaryId" type="radio" :value="location.id" />主要</label><span><strong>{{ location.name }}</strong><small>{{ location.admin1_name }}</small></span><button type="button" :disabled="index === 0" @click="move(index, -1)">↑</button><button type="button" :disabled="index === selected.length - 1" @click="move(index, 1)">↓</button><button type="button" :disabled="selected.length === 1" @click="remove(location.id)">移除</button></article><div class="trip-location-add"><select v-model="addId"><option value="">选择其他地点</option><option v-for="location in unselected" :key="location.id" :value="String(location.id)">{{ location.name }} · {{ location.admin1_name }}</option></select><button type="button" class="secondary-button" :disabled="!unselected.length" @click="add">加入地点</button></div></div></div><label>开始时间<input v-model="startedAt" type="datetime-local" step="60" required /></label><label>结束时间<input v-model="endedAt" type="datetime-local" step="60" required /></label><label class="full-field">行程备注<textarea v-model="notes" rows="5" placeholder="天气、路线、同行者或器材等，可不填"></textarea></label></div></fieldset></div><footer class="dialog-footer"><span role="status">{{ status }}</span><button type="submit" class="primary-button" :disabled="!locations.length">保存行程</button></footer></form>
</template>
